#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

typedef long long ll;
typedef __int128 lll;

int N, M, K;
vector<ll> A;
vector<lll> dp_val;
vector<ll> dp_cnt;
vector<int> q;

// 在带罚分 C 的情况下，求最大价值和以及对应选取的个数
pair<lll, ll> check(lll C) {
    dp_val.assign(N + 2, 0);
    dp_cnt.assign(N + 2, 0);
    q.assign(N + 2, 0);
    int head = 0, tail = 0;
    
    // 初始状态：位置 0，价值 0，选取个数 0
    q[tail++] = 0;
    
    for (int i = 1; i <= N; ++i) {
        // 弹出超出滑动窗口 (距离 > M+1) 的状态
        while (head < tail && q[head] < i - M - 1) {
            head++;
        }
        
        int best_idx = q[head];
        dp_val[i] = dp_val[best_idx] + A[i] - C;
        dp_cnt[i] = dp_cnt[best_idx] + 1;
        
        // 维护单调队列，保证队首为最大价值。
        // 若价值相同，优先保留选取个数更多的（为了找上凸壳右端点，使得更容易 >= K）
        while (head < tail) {
            int last = q[tail - 1];
            if (dp_val[last] < dp_val[i] || (dp_val[last] == dp_val[i] && dp_cnt[last] <= dp_cnt[i])) {
                tail--;
            } else {
                break;
            }
        }
        q[tail++] = i;
    }
    
    // 处理虚拟终点 N+1，不增加价值，不增加选取个数
    int i = N + 1;
    while (head < tail && q[head] < i - M - 1) {
        head++;
    }
    int best_idx = q[head];
    
    return {dp_val[best_idx], dp_cnt[best_idx]};
}

int main() {
    // 优化输入输出流速度
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    if (!(cin >> N >> M >> K)) return 0;
    A.resize(N + 1);
    for (int i = 1; i <= N; ++i) {
        cin >> A[i];
    }
    
    // 1. 无解判定
    // 能够覆盖的最大长度为 K * (M + 1) + M
    if (N > (ll)K * (M + 1) + M) {
        cout << -1 << "\n";
        return 0;
    }
    
    // 2. 特判 C=0 的情况。如果此时最优选取个数 <= K，说明不需要限制就能取得全局最优
    auto res0 = check(0);
    if (res0.second <= K) {
        cout << (long long)res0.first << "\n";
        return 0;
    }
    
    // 3. WQS 二分寻找最优罚分
    // A[i] 在 [-10^9, 10^9]，N <= 2*10^5，斜率最大可达 2*10^14，因此二分边界设为 4e14 足够
    lll L = 0, R = (lll)4e14;
    lll ans = -1e18;
    while (L <= R) {
        lll mid = L + (R - L) / 2;
        auto res = check(mid);
        // 如果在罚分为 mid 时，最优解选取个数 >= K
        if (res.second >= K) {
            ans = res.first + mid * K;
            L = mid + 1; // 尝试增大罚分，使得选取个数减小并逼近 K
        } else {
            R = mid - 1;
        }
    }
    
    cout << (long long)ans << "\n";
    
    return 0;
}
